import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"How to Read Engineering Evidence at the Digital Employee Works","description":"","frontmatter":{},"headers":[],"relativePath":"en/methodology/evidence-boundaries.md","filePath":"en/methodology/evidence-boundaries.md","lastUpdated":1787474677000}'),n={name:"en/methodology/evidence-boundaries.md"};function i(s,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="how-to-read-engineering-evidence-at-the-digital-employee-works" tabindex="-1">How to Read Engineering Evidence at the Digital Employee Works <a class="header-anchor" href="#how-to-read-engineering-evidence-at-the-digital-employee-works" aria-label="Permalink to &quot;How to Read Engineering Evidence at the Digital Employee Works&quot;">​</a></h1><p><a href="./../../zh/methodology/evidence-boundaries">中文</a></p><p>An engineering article can draw on public specifications, first-party implementation inspection, controlled execution records, and independent material. They have different evidentiary force. Compressing them all into “verified” would mislead readers.</p><h2 id="four-kinds-of-material-answer-different-questions" tabindex="-1">Four kinds of material answer different questions <a class="header-anchor" href="#four-kinds-of-material-answer-different-questions" aria-label="Permalink to &quot;Four kinds of material answer different questions&quot;">​</a></h2><ol><li><strong>Public specifications and papers</strong> define a concept, data format, or constraint. They do not prove that a particular product implements it.</li><li><strong>Narrow excerpts from a private implementation</strong> show that a particular interface or contract existed in the inspected commit. They are not open source, cannot be fully reproduced by the public, and do not prove that every endpoint or platform has the same behavior.</li><li><strong>Controlled tests, builds, and restart records</strong> show what happened on named tested paths in a defined environment. They are not independent reproduction, security certification, cross-platform reliability, or coverage of every branch.</li><li><strong>Independent standards, official documentation, and third-party research</strong> provide general context and an external reference point. They do not endorse a particular in-house project.</li></ol><p>This separation follows TMPA Core&#39;s four evidence levels: specified, implemented, demonstrated, and independently adopted. <a href="./../publications/tmpa-core-specification-s1.0#113-publication-and-evidence-boundaries">TMPA Core S1.0 §11.3</a> explains why a specification, code, bounded execution, and independent adoption cannot substitute for one another.</p><h2 id="how-to-read-code-excerpts-and-test-figures" tabindex="-1">How to read code excerpts and test figures <a class="header-anchor" href="#how-to-read-code-excerpts-and-test-figures" aria-label="Permalink to &quot;How to read code excerpts and test figures&quot;">​</a></h2><p>A code block states its source version, whether it comes from a private implementation, and whether it is a field-level excerpt or a structured reading aid. Omitted fields are not evidence that those fields do not exist or are unimportant; the article must not infer capability from the omission.</p><p>Read test figures together with their test set, environment, and directly covered mechanism. A large full-regression total does not automatically prove complete coverage of a particular state, fault branch, or security boundary. If an article does not enumerate the cases, read the figure as “these tested paths passed,” not “every possible path is proven.”</p><h2 id="how-to-read-does-not-support" tabindex="-1">How to read “does not support” <a class="header-anchor" href="#how-to-read-does-not-support" aria-label="Permalink to &quot;How to read “does not support”&quot;">​</a></h2><p>“Does not support” is not a courtesy disclaimer. It states what the present evidence cannot establish: a checked entry point does not prove no other entry point exists; one successful local restart does not prove recovery from every crash point; an atomic file replacement does not prove cross-host consistency or writer exclusion.</p><p>When the material cannot decide mechanically, an article should preserve uncertainty and name the next validation instead of presenting a plausible guess as fact. See <a href="./../about#research-method">About the Digital Employee Works</a> for the broader research method.</p>',12)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
